# %% ../nbs/00_data.ipynb #f1a00003
import os, re
from pathlib import Path
import numpy as np, pandas as pd
import ossl_fuku_transfer
from soilspecdata.readers import load_spa, read_spa
from soilspecdata.types import Spectra

# %% ../nbs/00_data.ipynb #f1a00007
def data_path()->Path: # Folder holding the data shared by the soilspec projects
    "The `SOILSPEC_DATA` folder if that variable is set, else `data/` in the soilspec workspace"
    p = os.environ.get('SOILSPEC_DATA')
    return Path(p) if p else Path(ossl_fuku_transfer.__file__).parents[2]/'data'

def fuku_path()->Path: # Folder holding the Fukushima data
    "The `fukushima` folder of `data_path()`"
    return data_path()/'fukushima'

# %% ../nbs/00_data.ipynb #f1a00011
def load_props()->pd.DataFrame: # One row per sample, indexed by sample ID
    "Soil properties of the Fukushima samples"
    df = pd.read_csv(fuku_path()/'MIRS_rawData'/'WetData_2013_2023.csv').dropna(subset=['ID'])
    return df.assign(ID=df.ID.astype(int).astype(str)).set_index('ID')

# %% ../nbs/00_data.ipynb #f1a00029
mg_k2o_per_cmolc = 47.1 # mg K₂O per 100 g of soil in 1 cmolc/kg of exchangeable K

# %% ../nbs/00_data.ipynb #f1a00016
excluded = { # Sample ID: reason for leaving the sample out
    **{i: 'scans by two operators disagree' for i in ('748', '989', '1165', '1986')},
    **{i: '`.spa` file differs from its absorbance CSV export' for i in ('1943', '2346', '2430', '2529', '2532')},
    '1531': 'unlettered `.spa` file beside replicates a-d',
    '177': 'duplicate `.spa` file for replicate b',
    '1984': 'earlier processed spectrum does not match the `.spa` files',
}

# %% ../nbs/00_data.ipynb #f1a00017
def spa_files()->dict: # Sample ID: `.spa` files of its replicates
    "The `.spa` files of the Fukushima soil samples, by sample ID"
    res = {}
    for f in sorted((fuku_path()/'MIRS_rawData'/'Thermo'/'original').glob('FukushimaSoil_*/*')):
        m = re.match(r'^\d+', f.name)
        if m and f.suffix.lower() == '.spa': res.setdefault(m[0], []).append(f)
    return res

def sample_ids()->np.ndarray: # Sample IDs, in increasing order
    "IDs of the samples in the current selection"
    ref = set(pd.read_csv(fuku_path()/'reference'/'cs137_ratio_metadata.csv', usecols=['ID']).ID.astype(str))
    return np.array(sorted((ref & set(spa_files())) - set(excluded), key=int))

# %% ../nbs/00_data.ipynb #f1a00032
def cs137_split()->tuple: # (training IDs, test IDs), each in increasing order
    "Training and test sample IDs of the Cs137 ratio study, within the current selection"
    ids = sample_ids()
    test = pd.read_csv(fuku_path()/'reference'/'cs137_ratio_test.csv', usecols=['ID']).ID.astype(str)
    is_test = np.isin(ids, test)
    return ids[~is_test], ids[is_test]

# %% ../nbs/00_data.ipynb #f1a00035
def sample_batches(
    ids, # Sample IDs
)->np.ndarray: # Batch label of each sample, such as 'batch 1'
    "The measurement batch of each sample"
    files = spa_files()
    dirs = sorted({fs[0].parent.name for fs in files.values()})
    return np.array([f'batch {dirs.index(files[i][0].parent.name) + 1}' for i in ids])

# %% ../nbs/00_data.ipynb #f1a00044
mg_mgo_per_cmolc = 20.15 # mg MgO per 100 g of soil in 1 cmolc/kg of exchangeable Mg
mg_cao_per_cmolc = 28.04 # mg CaO per 100 g of soil in 1 cmolc/kg of exchangeable Ca
shared_props = ['K', 'Mg', 'Ca', 'CEC', 'C', 'N', 'pH'] # Properties measured in both datasets

def fuku_shared_props(
    ids=None, # Sample IDs; defaults to `sample_ids()`
)->pd.DataFrame: # One row per sample: `shared_props` and clay, in cmolc/kg, % and pH units
    "The Fukushima properties shared with OSSL, in OSSL's units, with clay and the soil type"
    p = load_props().reindex(sample_ids() if ids is None else ids)
    return pd.DataFrame({'K': p['soil_ex_K2O'] / mg_k2o_per_cmolc, 'Mg': p['soil_MgO'] / mg_mgo_per_cmolc, 'Ca': p['soil_CaO'] / mg_cao_per_cmolc,
                         'CEC': p['soil_CEC'], 'C': p['soil_C'], 'N': p['soil_N'], 'pH': p['soil_pH(H2O)'], 'clay': p['clay'],
                         'soil': p['Soil_type_describe']})

def ossl_shared_props(
    spectra, # OSSL `Spectra`, such as from `load_ossl().mir()`
)->pd.DataFrame: # One row per sample of `spectra`: `shared_props` and clay
    "The OSSL properties shared with Fukushima, with clay, and whether the soil is an Andisol"
    cols = {'K': 'k.ext_usda.a725_cmolc.kg', 'Mg': 'mg.ext_usda.a724_cmolc.kg', 'Ca': 'ca.ext_usda.a722_cmolc.kg', 'CEC': 'cec_usda.a723_cmolc.kg',
            'C': 'c.tot_usda.a622_w.pct', 'N': 'n.tot_usda.a623_w.pct', 'pH': 'ph.h2o_usda.a268_index', 'clay': 'clay.tot_usda.a334_w.pct'}
    src = spectra.source.df.reindex(spectra.sample_ids)
    res = pd.DataFrame({k: src[c] for k, c in cols.items()})
    great_group = src['pedon.taxa_usda_txt'].str.lower().str.strip().str.extract(r'(\w+)$')[0]
    return res.assign(andisol=great_group.str.endswith('and').fillna(False).astype(bool))

def prop_features(
    df:pd.DataFrame, # Properties from `fuku_shared_props` or `ossl_shared_props`
    cols=shared_props, # Columns to use
)->pd.DataFrame: # The samples with all `cols`
    "`log1p` of every property in `cols` but pH, after clipping negative values at 0, for the samples with all of them"
    return df[cols].apply(lambda s: s if s.name == 'pH' else np.log1p(s.clip(lower=0))).dropna()

# %% ../nbs/00_data.ipynb #f1a00039
def bruker_files()->dict: # Sample ID: CSV files of its replicates
    "The CSV exports of the Bruker spectra of the Fukushima soil samples, by sample ID"
    res = {}
    for f in sorted((fuku_path()/'MIRS_rawData'/'Bruker'/'csv'/'FukushimaSoil').glob('*.csv')):
        m = re.match(r'^(\d+)(?:_\d|[a-d])\.csv$', f.name)
        if m: res.setdefault(m[1], []).append(f)
    return res

def load_bruker(
    wns, # Wavenumbers to interpolate onto, in cm⁻¹, in increasing order
    ids=None, # Sample IDs to load; defaults to every sample in `bruker_files()`
)->Spectra: # One spectrum per sample, with the soil properties in `source`
    "Load the Bruker spectra, averaging the replicates of each sample"
    files, wns = bruker_files(), np.asarray(wns)
    ids = sorted(files, key=int) if ids is None else list(ids)
    spectra = []
    for i in ids:
        reps = []
        for f in files[i]:
            d = pd.read_csv(f).sort_values('wavenumber')
            x = d.wavenumber.to_numpy()
            if wns[0] < x[0] or wns[-1] > x[-1]: raise ValueError(f"{f.name} covers {x[0]:.2f}–{x[-1]:.2f} cm⁻¹, which does not include `wns`")
            reps.append(np.interp(wns, x, d.absorbance.to_numpy()))
        spectra.append(np.mean(reps, axis=0))
    return Spectra(wavenumbers=wns, spectra=np.stack(spectra), measurement_type='abs', sample_ids=np.array(ids), source=load_props())

# %% ../nbs/00_data.ipynb #f1a00021
shared_wns = np.arange(650, 3999, 2) # Wavenumbers that OSSL and every Fukushima batch cover, in cm⁻¹

def load_fuku(
    wns=shared_wns, # Wavenumbers to interpolate onto, in cm⁻¹, in increasing order
    ids=None, # Sample IDs to load; defaults to `sample_ids()`
)->Spectra: # One spectrum per sample, with the soil properties in `source`
    "Load the Fukushima spectra, averaging the replicates of each sample"
    files = spa_files()
    ids = sample_ids() if ids is None else ids
    res = load_spa([f for i in ids for f in files[i]], wns)
    res.source = load_props()
    return res

# %% ../nbs/00_data.ipynb #f1a00048
def load_replicates(
    wns=shared_wns, # Wavenumbers to interpolate onto, in cm⁻¹, in increasing order
    ids=None, # Sample IDs to load; defaults to `sample_ids()`
)->Spectra: # One spectrum per `.spa` file, with the soil properties in `source`
    "Load every replicate of the Fukushima samples as its own spectrum"
    files, wns = spa_files(), np.asarray(wns)
    ids = sample_ids() if ids is None else ids
    rows, sids = [], []
    for i in ids:
        for f in files[i]:
            x, vals, mtype = read_spa(f)
            rows.append(np.interp(wns, x, vals))
            sids.append(i)
    res = Spectra(wavenumbers=wns, spectra=np.stack(rows), measurement_type=mtype, sample_ids=np.array(sids))
    res.source = load_props()
    return res
